def monotone_width(circuit):
    n = len(circuit)
    max_inputs = 0
    stack = []

    for i in range(n):
        if circuit[i] == 1:
            stack.append(i + 1)
        else:
            while stack and stack[-1] > i + 1:
                stack.pop()
            if stack:
                max_inputs = max(max_inputs, stack[-1])

    return max_inputs

